def transform(g):
    h,w=len(g),len(g[0])
    mc=None
    for j in range(w):
        col={g[i][j] for i in range(h)}
        if len(col)==1:
            v=next(iter(col))
            if all(g[i][jj]!=v for i in range(h) for jj in range(w) if jj!=j):
                mc=j; break
    L=[r[:mc] for r in g]; R=[r[mc+1:] for r in g]
    shared=(set(x for r in L for x in r) & set(x for r in R for x in r))
    sc=sorted(shared)[0] if shared else 0
    return [[3 if L[i][j]==R[i][j] else sc for j in range(len(L[0]))] for i in range(h)]
for i in (1,2,3):
    print(i, transform(G['Demo pair %d input'%i])==G['Demo pair %d output'%i])
